head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vTrdDd = '';
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const prt = $c.frame.path("../");
        if (prt !== undefined) {
            scwin.fn_GetPar = prt.scwin.fn_GetPar;
        }
        if (scwin.fn_GetPar !== undefined) {
            const arrPar = new Array();
            scwin.fn_GetPar(arrPar);
            scwin.vTrdDd = arrPar[0].TRD_DD;
            url += "&SCREN_ID=" + "ULDBNS30301.xml";
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            url += "&TRD_DD=" + scwin.vTrdDd;
            const sbmOptions = {
                id : "sbm_dts_MktFile",
                action : "/bns/BnsCommon.do",
                ref : "",
                target : "dts_MktFile=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30301.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30301.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_MktFile_OnLoadError
 * @description dts_MktFile 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MktFile_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30301.dts_MktFile_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MktFile_OnLoadCompleted
 * @description dts_MktFile 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MktFile_OnLoadCompleted = async function(rowcount) {
    try {
        if (rowcount > 0) {
            txb_SendYn.setValue('Y');
            txb_TrdDd.setValue(dts_MktFile.getCellData(1, 'TRD_DD') + ' ' + dts_MktFile.getCellData(1, 'TRNSM_TM'));
            txa_Binfile.setValue(dts_MktFile.getCellData(1, 'BINFILE'));
        } else {
            txb_SendYn.setValue('N');
            txb_TrdDd.setValue('-');
            await $c.win.alert('시장지 데이터가 없습니다.');
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30301.dts_MktFile_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_DownloadFile_onclick
 * @description 「파일저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_DownloadFile_onclick = function() {
    try {
        if (txb_SendYn.getValue() === '' ||
            txb_SendYn.getValue() === 'N') return;
        let url = "/bns/BnsMktactFileDownload.do?";
        url += "TRD_DD=" + scwin.vTrdDd;
        location.href = url;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS30301.btn_DownloadFile_onclick" });
    }
};
